    bv=g[br][0]
    seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and g[i][j]!=bv and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=0 and g[ny][nx]!=bv and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                comps.append(comp)
    # gravity toward bar: direction sign
    up = br < H//2
    def dist(c):
        return min(abs(y-br) for y,x in c)
    comps.sort(key=lambda c:dist(c))  # closest to bar processes first? try variants
    out=[[0]*W for _ in range(H)]
    occ=set()
    for c in comps:
        s=-1 if up else 1
        dy=0
        while True:
            nxt=[(y+s,y,x) for y,x in [] ]
            blocked=False
            for y,x in c:
                ny=y+s
                if ny==br or (ny,x) in occ:
                    blocked=True; break
            if blocked: break
            dy+=s
        for y,x in c: out[y+dy][x]=g[y][x]; occ.add((y+dy,x))
    return out
